import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"도(道)란 무엇인가","slug":"도-道-란-무엇인가","link":"#도-道-란-무엇인가","children":[]},{"level":2,"title":"무위(無爲)의 정치","slug":"무위-無爲-의-정치","link":"#무위-無爲-의-정치","children":[]}],"relativePath":"philosophy/China/04. 도가와 노자.md","filePath":"philosophy/China/04. 도가와 노자.md"}'),e={name:"philosophy/China/04. 도가와 노자.md"};function a(l,t,i,p,g,_){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="도-道-란-무엇인가" tabindex="-1">도(道)란 무엇인가 <a class="header-anchor" href="#도-道-란-무엇인가" aria-label="Permalink to &quot;도(道)란 무엇인가&quot;">​</a></h2><p>노자는 <strong>도에 따르는 것</strong>이 중요하다고 주장 — <strong>도법자연(道法自然)</strong>, 도는 자연을 본받는다.</p><ul><li><strong>도</strong>: 본래 &#39;길&#39;을 의미하는 글자였으나, 노자에게는 <strong>우주의 법칙</strong>을 뜻함. 인간도 우주에 속하는 존재이므로 도를 따라야 함</li><li><strong>자연(自然)</strong>: 오늘날 말하는 &quot;nature&quot;(자연환경)가 아니라, 글자 그대로 <strong>&quot;스스로 그러함&quot;</strong> — 어떤 것이 외부의 개입 없이 본래성에 따라 스스로 그렇게 드러나도록 하는 것</li></ul><p><strong>우주에서 자연을 거스르는 유일한 존재가 인간</strong>: 인간은 있는 그대로의 세계를 받아들이지 못하고, <strong>개념화</strong>를 통해 받아들임. 대상을 가치화하고 거기에 주관적 가치를 부여함 → 좋은 것을 소유하려는 욕망이 생기고, 이 욕망으로부터 갈등과 혼란이 발생.</p><p><strong>도가도 비상도, 명가명 비상명(道可道 非常道, 名可名 非常名)</strong>: 말로 표현할 수 있는 도는 (영원한) 도가 아니며, 이름 붙일 수 있는 이름은 영원한 이름이 아님 — 언어는 존재하는 대상을 온전히 표현할 수 없음.</p><p><strong>그런데 왜 굳이 &quot;도&quot;라고 부르는가?</strong>: 도를 언어로 명확히 표현할 수는 없지만, 그것을 가리켜 이야기하려면 어쨌든 이름이 필요하기 때문 — 부득이하게 붙인 임시적 명칭이라는 의미.</p><p><strong>도의 성격</strong>: 우주 만물의 근원이며, 무규정적(어떤 고정된 형태나 속성으로 한정되지 않음)이고, 자연적 질서이며, 동시에 정치와 삶의 기준이 됨.</p><h2 id="무위-無爲-의-정치" tabindex="-1">무위(無爲)의 정치 <a class="header-anchor" href="#무위-無爲-의-정치" aria-label="Permalink to &quot;무위(無爲)의 정치&quot;">​</a></h2><p><strong>무위</strong>는 &quot;아무것도 하지 않는 것&quot;이 아니라, 인위적으로 억지로 개입하거나 강제하지 않고 사물이 스스로 그러한 대로(자연) 흘러가도록 둔다는 뜻. 통치자가 인위적인 규제·욕망·간섭을 최소화할수록 백성이 본래의 자연스러운 삶을 되찾고 오히려 잘 다스려진다는 역설적 정치론.</p><p><strong>소국과민(小國寡民)</strong>: 노자가 그리는 이상적 공동체 상 — 나라는 작고 백성은 적어, 문명의 인위적 발전(도구, 지식, 욕망의 확대)에 휘둘리지 않고 소박하고 자족적인 삶을 사는 상태.</p>',10)])])}const c=o(e,[["render",a]]);export{u as __pageData,c as default};
